-- Check: sample records per register (10 each).
SELECT l.register_key, count(r.id) AS records
FROM public.local_registers l
LEFT JOIN public.local_register_records r ON r.register_id = l.id AND r.is_deleted = FALSE
WHERE l.id IN ('00000000-0000-4000-9002-000000000024'::uuid, '00000000-0000-4000-9002-000000000025'::uuid, '00000000-0000-4000-9002-000000000026'::uuid, '00000000-0000-4000-9002-000000000027'::uuid, '00000000-0000-4000-9002-000000000028'::uuid, '00000000-0000-4000-9002-000000000029'::uuid, '00000000-0000-4000-9002-00000000002a'::uuid, '00000000-0000-4000-9002-00000000002b'::uuid, '00000000-0000-4000-9002-00000000002c'::uuid, '00000000-0000-4000-9002-00000000002d'::uuid)
GROUP BY l.register_key ORDER BY l.register_key;
